const { store } = require('./src/db.js');
const fs = require('fs');
const path = require('path');

// Clean up any existing data.json
const dataFile = path.join(__dirname, 'data.json');
if (fs.existsSync(dataFile)) {
  fs.unlinkSync(dataFile);
  console.log('Cleaned up existing data.json');
}

// Test 1: Save data
console.log('Test 1: Saving data...');
const id1 = store.save({ name: 'Alice', age: 30 });
console.log(`Saved item 1, returned ID: ${id1}`);

const id2 = store.save({ name: 'Bob', age: 25 });
console.log(`Saved item 2, returned ID: ${id2}`);

// Test 2: Verify data.json exists and has correct content
console.log('\nTest 2: Checking data.json file...');
if (fs.existsSync(dataFile)) {
  const fileContent = fs.readFileSync(dataFile, 'utf8');
  console.log(`data.json exists with content: ${fileContent}`);
  const data = JSON.parse(fileContent);
  console.log(`Parsed data has ${data.length} items`);
} else {
  console.error('ERROR: data.json does not exist!');
  process.exit(1);
}

// Test 3: Load data from disk in a new store instance
console.log('\nTest 3: Creating new store instance and loading from disk...');
const { store: store2 } = require('./src/db.js');
const loadedData = store2.load();
console.log(`Loaded ${loadedData.length} items from disk`);
console.log(`Loaded data:`, JSON.stringify(loadedData, null, 2));

if (loadedData.length === 2 && loadedData[0].name === 'Alice' && loadedData[1].name === 'Bob') {
  console.log('\n✓ SUCCESS: Data correctly persisted and loaded from data.json');
  process.exit(0);
} else {
  console.error('\n✗ FAILURE: Data not correctly persisted');
  process.exit(1);
}
EOF
